using TrEInvoice.Core; using TrEInvoice.Calculation;
namespace TrEInvoice.Calculation.Tests;
public class CalculationTests { static InvoiceDocument Invoice(params InvoiceLine[] lines)=>new("INV",Guid.NewGuid(),new DateOnly(2026,1,1),"TRY",new("Seller"),new("Buyer"),lines, [new(new("VAT","VAT style","Tax"),20,new(0,"TRY"))],new(new(0,"TRY"),new(0,"TRY"),new(0,"TRY"),new(0,"TRY"),new(0,"TRY"),new(0,"TRY"))); static InvoiceLine L(decimal q,decimal p,decimal allowance=0,decimal charge=0)=>new("1","item",q,new(p,"TRY"),new(0,"TRY"),[],new(allowance,"TRY"),new(charge,"TRY")); [Fact] public void Calculates_single_line_and_tax(){var x=new InvoiceCalculator().Calculate(Invoice(L(2,10)),CalculationOptions.Default); Assert.Equal(20,x.Totals.TaxExclusiveAmount.Value); Assert.Equal(24,x.Totals.TaxInclusiveAmount.Value);} [Fact] public void Calculates_multiple_lines_and_rounding(){var x=new InvoiceCalculator().Calculate(Invoice(L(2,10),L(3,0.335m)),new(new(2))); Assert.Equal(21.01m,x.Totals.TaxExclusiveAmount.Value);} [Fact] public void Calculates_allowance_and_charge_and_taxable_base(){var i=Invoice(L(1,100,10,5)); var x=new InvoiceCalculator().Calculate(i,CalculationOptions.Default); Assert.Equal(95,x.Totals.TaxExclusiveAmount.Value); Assert.Equal(19,x.Taxes[0].Amount.Value); Assert.Equal(114,x.Totals.TaxInclusiveAmount.Value);} [Fact] public void Withholding_reduces_payable(){var i=Invoice(L(1,100)) with { Taxes=[new(new("W","Withholding","Custom"),0,new(0,"TRY"),10)]}; var x=new InvoiceCalculator().Calculate(i,CalculationOptions.Default); Assert.Equal(90,x.Totals.PayableAmount.Value);} [Fact] public void Configurable_tolerance_allows_small_difference(){var i=Invoice(L(1,100)) with {Taxes=[new(new("VAT","VAT","Tax"),20,new(20,"TRY"))],Totals=new(new(100,"TRY"),new(100,"TRY"),new(120,"TRY"),new(120.005m,"TRY"),new(0,"TRY"),new(0,"TRY"))}; var r=new TotalReconciler().Reconcile(i,new(new(),0.01m)); Assert.True(r.IsReconciled);} [Fact] public void Mismatch_is_reported(){var i=Invoice(L(1,100)); var r=new TotalReconciler().Reconcile(i,CalculationOptions.Default); Assert.False(r.IsReconciled); Assert.NotEmpty(r.Issues);} [Fact] public void Negative_tolerance_and_invalid_scale_are_rejected(){Assert.Throws<ArgumentOutOfRangeException>(()=>new CalculationOptions(new(),-0.1m)); Assert.Throws<ArgumentOutOfRangeException>(()=>new RoundingPolicy(29));} }
